        if (stack.length < 1) {
          throw new Error('Invalid expression');
        }
        const a = stack.pop();
        stack.push(-a);
      } else {
        // Binary operator
        if (stack.length < 2) {
          throw new Error('Invalid expression');
        }
        const b = stack.pop();
        const a = stack.pop();

